-- Minimal structural fixture of the production discovery sources (no user data).
create role anon; create role authenticated; create role service_role;
create table public.waouh_articles(
"id" uuid,
"seller_id" uuid,
"title" text,
"description" text,
"category" text,
"brand" text,
"model" text,
"condition" text,
"price" numeric,
"currency" text,
